/* ---- periodization factory ---- */
/* kind: comp | acc | iso | core */
function prog(sets, loadB1, rest, kind){
 const R={comp:{b1:['10-12','7-8'],b2:['8-10','8'],b3:['6-8','8-9'],dl:['8-10','5-6']},
          acc:{b1:['12-15','7-8'],b2:['10-12','8'],b3:['8-10','8-9'],dl:['12','5-6']},
          iso:{b1:['15','8'],b2:['12-15','8'],b3:['10-12','8-9'],dl:['12','5-6']},
          core:{b1:['30-45s','—'],b2:['45-60s','—'],b3:['45-60s','—'],dl:['30s','—']}}[kind];
 const s3=kind==='comp'?sets+1:sets;
 return {
  b1:{s:sets,r:R.b1[0],rpe:R.b1[1],l:loadB1,rest},
  b2:{s:sets,r:R.b2[0],rpe:R.b2[1],l:'base + carga',rest},
  b3:{s:s3, r:R.b3[0],rpe:R.b3[1],l:'pesada',rest},
  dl:{s:Math.max(2,sets-1),r:R.dl[0],rpe:R.dl[1],l:'carga B2',rest}
 };
}
const I=(ex,factory,note)=>({ex,...factory,note});

